def int_bits(t0, value):
    v = value + (1 << t0); k = v.bit_length()
    return (k-1-t0) + 1 + (k-1)
def litb(b): return 2 + int_bits(4,b)
def matb(d,l): return 1 + int_bits(5,d-1) + int_bits(2,l-1)

head={}; prev=[-1]*n; ranges=[None]*n
for i in range(n):
    ranges[i]=[]
    if i+4<=n:
        k=data[i]<<24|data[i+1]<<16|data[i+2]<<8|data[i+3]
        p=head.get(k,-1); maxlen=n-i; cand=[]; cnt=0
        while p>=0 and cnt<5000:
            l=0
            while l<maxlen and data[p+l]==data[i+l]: l+=1
            if l>=5: cand.append((i-p,l))
            p=prev[p]; cnt+=1
        if cand:
            cand.sort()
            covered=4
            for d,l in cand:
                if l>covered:
                    ranges[i].append((covered+1,l,d)); covered=l
                    if covered==maxlen: break
        prev[i]=head.get(k,-1); head[k]=i

import math
dp=[0.0]*(n+1); ch=[None]*n
